package ru.stepanov.selfcontrol.scenario; import jakarta.persistence.*; import ru.stepanov.selfcontrol.common.Money; import java.time.Instant; @Embeddable public class TriggerSnapshot{ @Column(name="transaction_id") private String transactionID; private String mcc; private String merchantName; @Embedded @AttributeOverrides({@AttributeOverride(name="amount",column=@Column(name="trigger_amount",precision=19,scale=2)),@AttributeOverride(name="currency",column=@Column(name="trigger_currency"))}) private Money amount; private Instant occurredAt; private String attribute; public String getTransactionID(){return transactionID;} public void setTransactionID(String transactionID){this.transactionID=transactionID;} public String getMcc(){return mcc;} public void setMcc(String mcc){this.mcc=mcc;} public String getMerchantName(){return merchantName;} public void setMerchantName(String merchantName){this.merchantName=merchantName;} public Money getAmount(){return amount;} public void setAmount(Money amount){this.amount=amount;} public Instant getOccurredAt(){return occurredAt;} public void setOccurredAt(Instant occurredAt){this.occurredAt=occurredAt;} public String getAttribute(){return attribute;} public void setAttribute(String attribute){this.attribute=attribute;} }
